import type OpenAI from 'openai';

import { forEachSequential } from '../common/async-sequence';
import type { StructuredLogger } from '../logging/structured-logger';
import type { ActionEntry, ToolArgs } from './unified-agent.types';
import { isAllowedTool, parseToolArgs } from './unified-agent-tool-parser.helpers';

type UnknownRecord = Record<string, unknown>;

export async function processUnifiedAgentToolCalls(
  toolCalls: OpenAI.Chat.ChatCompletionMessageToolCall[],
  deps: {
    workspaceId: string;
    contactId: string;
    phone: string;
    allowedTools?: string[];
    context?: UnknownRecord;
    logger: StructuredLogger;
    logAutopilotEvent: (
      workspaceId: string,
      contactId: string,
      tool: string,
      args: ToolArgs,
      result: unknown,
    ) => Promise<unknown>;
    executeTool: (
      workspaceId: string,
      contactId: string,
      phone: string,
      tool: string,
      args: ToolArgs,
      context?: UnknownRecord,
    ) => Promise<unknown>;
  },
): Promise<ActionEntry[]> {
  const { workspaceId, contactId, phone, allowedTools, context, logger, logAutopilotEvent, executeTool } = deps;

  const actionsList: ActionEntry[] = [];

  await forEachSequential(toolCalls, async (toolCall) => {
    if (toolCall.type !== 'function') {
      return;
    }
    const toolName = toolCall.function.name;
    if (!isAllowedTool(toolName, allowedTools)) {
      logger.warn(
        `Blocked disallowed agent tool call: workspaceId=${workspaceId} tool=${toolName}`,
      );
      const blockedResult = { blocked: true, reason: 'capability_not_allowed' };
      actionsList.push({ tool: toolName, args: {}, result: blockedResult });
      await logAutopilotEvent(workspaceId, contactId, toolName, {}, blockedResult);
      return;
    }
    const toolArgs: Record<string, unknown> = parseToolArgs(toolCall.function.arguments);
    const result = await executeTool(
      workspaceId,
      contactId,
      phone,
      toolName,
      toolArgs as ToolArgs,
      context,
    );
    actionsList.push({ tool: toolName, args: toolArgs as ToolArgs, result });
    await logAutopilotEvent(workspaceId, contactId, toolName, toolArgs as ToolArgs, result);
  });

  return actionsList;
}

import type OpenAI from 'openai';

import type { StructuredLogger } from '../logging/structured-logger';
import type { PlanLimitsService } from '../billing/plan-limits.service';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { ActionEntry, PredecidedAction, ToolArgs } from './unified-agent.types';
import {
  buildPredecidedActionDraft,
  executePredecidedAgentActions,
} from './unified-agent-predecided-actions.part';
import { recordAgentRuntimeTurn } from './unified-agent-runtime.helpers';
import type { AgentRuntimeContextService } from './agent-runtime';

type UnknownRecord = Record<string, unknown>;

export async function processUnifiedAgentPredecidedActions(params: {
  allowedTools?: string[];
  contactId: string;
  context?: UnknownRecord;
  conversationHistory: Array<{ role: string; content: unknown }>;
  executeTool: (
    workspaceId: string,
    contactId: string,
    phone: string,
    tool: string,
    args: ToolArgs,
    context?: UnknownRecord,
  ) => Promise<unknown>;
  fallbackWriterModel: string;
  logAutopilotEvent: (
    workspaceId: string,
    contactId: string,
    tool: string,
    args: ToolArgs,
    result: unknown,
  ) => Promise<unknown>;
  message: string;
  openai: OpenAI | null;
  phone: string;
  planLimits: PlanLimitsService;
  predecidedActions: PredecidedAction[];
  response: UnifiedAgentResponseService;
  writerModel: string;
  workspaceId: string;
  agentRuntime?: AgentRuntimeContextService;
  channel: string;
  logger: StructuredLogger;
}): Promise<{
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
}> {
  const {
    allowedTools,
    contactId,
    context,
    conversationHistory,
    executeTool,
    fallbackWriterModel,
    logAutopilotEvent,
    message,
    openai,
    phone,
    planLimits,
    predecidedActions,
    response,
    writerModel,
    workspaceId,
    agentRuntime,
    channel,
    logger,
  } = params;

  const actionsList = await executePredecidedAgentActions({
    ...(allowedTools !== undefined ? { allowedTools } : {}),
    contactId,
    ...(context !== undefined ? { context } : {}),
    executeTool,
    logAutopilotEvent,
    phone,
    predecidedActions,
    workspaceId,
  });

  const intent = response.extractIntent(actionsList, message);
  const draftedReply = await response.composeWriterReply(
    openai,
    writerModel,
    fallbackWriterModel,
    {
      workspaceId,
      customerMessage: message,
      assistantDraft: buildPredecidedActionDraft(actionsList),
      actions: actionsList,
      historyTurns: conversationHistory.length,
    },
  );

  await recordAgentRuntimeTurn(agentRuntime, {
    workspaceId,
    channel,
    userMessage: message,
    ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
    contactId,
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
    actions: actionsList.map((action) => ({
      toolName: action.tool,
      success: actionSucceededFromToolRouter(action.result),
      result: action.result,
    })),
  });

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
  };
}

function actionSucceededFromToolRouter(result: unknown): boolean {
  if (!result || typeof result !== 'object' || Array.isArray(result)) {
    return false;
  }
  const record = result as Record<string, unknown>;
  return record.success === true || record.ok === true || record.executed === true;
}

