import type { ActionEntry } from './unified-agent.types';

type UnknownRecord = Record<string, unknown>;

export async function processIncomingUnifiedAgentMessage(
  processMessage: (params: {
    allowedTools?: string[];
    workspaceId: string;
    contactId: string;
    phone: string;
    message: string;
    context?: UnknownRecord;
  }) => Promise<{
    actions: ActionEntry[];
    response?: string;
    intent: string;
    confidence: number;
  }>,
  params: {
    workspaceId: string;
    phone: string;
    message: string;
    contactId?: string;
    channel?: string;
    context?: UnknownRecord;
    executeTools?: boolean;
  },
): Promise<{
  reply?: string;
  response?: string;
  actions: ActionEntry[];
  intent: string;
  confidence: number;
}> {
  const result = await processMessage({
    workspaceId: params.workspaceId,
    contactId: params.contactId || '',
    phone: params.phone,
    message: params.message,
    context: {
      channel: params.channel || 'whatsapp',
      executeTools: params.executeTools !== false,
      ...(params.context || {}),
    },
  });

  return {
    actions: result.actions,
    intent: result.intent,
    confidence: result.confidence,
    ...(result.response !== undefined
      ? { reply: result.response, response: result.response }
      : {}),
  };
}

